#!/bin/sh
# Remove byte-code generated by postinstall, but only on a real uninstall:
# rpm passes "1" and dpkg "upgrade" when the package is being upgraded.
case "$1" in
    1|upgrade|failed-upgrade) exit 0 ;;
esac
find /usr/share/open-headset -name '__pycache__' -type d -prune -exec rm -rf {} + 2>/dev/null || true
exit 0
